prompts.raw:
function ({ vars }) {
  return JSON.stringify([
    { role: 'system', content: MEDITATION_SYSTEM_PROMPT },
    {
      role: 'user',
      content: buildUserPrompt({
        prompt: vars.prompt,
        type: vars.type,
        durationMinutes: parseInt(vars.duration, 10),
        language: vars.language,
      }),
    },
  ]);
}
